#include <vector>
#include <string>
#include <algorithm>
#include <cstdlib>
int windowed_pickup_delivery(std::vector<int> weights, int capacity, std::vector<int> travel, std::vector<int> appointments) {
    int n = static_cast<int>(weights.size());
    if (n == 0) return 0;

    int m = 2 * n;
    int states = 1 << m;
    const int INF = 1000000000;
    std::vector<int> load(states, 0);
    for (int mask = 1; mask < states; ++mask) {
        int bit = __builtin_ctz(static_cast<unsigned>(mask));
        int prev = mask & (mask - 1);
        load[mask] = load[prev];
        if (bit < n) load[mask] += weights[bit];
        else load[mask] -= weights[bit - n];
    }

    std::vector<std::vector<int>> dp(states, std::vector<int>(m + 1, INF));
    dp[0][0] = 0;

    for (int mask = 0; mask < states; ++mask) {
        for (int last = 0; last <= m; ++last) {
            int time = dp[mask][last];
            if (time == INF) continue;
            for (int j = 0; j < m; ++j) {
                int bit = 1 << j;
                if (mask & bit) continue;
                if (j < n) {
                    if (load[mask] + weights[j] > capacity) continue;
                } else {
                    int i = j - n;
                    if ((mask & (1 << i)) == 0) continue;
                }

                int point = j + 1;
                int arrival = time + travel[last * (m + 1) + point];
                int open = appointments[3 * j];
                int close = appointments[3 * j + 1];
                int start = std::max(arrival, open);
                if (start > close) continue;
                int finish = start + appointments[3 * j + 2];
                int nextMask = mask | bit;
                if (finish < dp[nextMask][point])
                    dp[nextMask][point] = finish;
            }
        }
    }

    int best = INF;
    int full = states - 1;
    for (int last = 1; last <= m; ++last) {
        if (dp[full][last] == INF) continue;
        best = std::min(best, dp[full][last] + travel[last * (m + 1)]);
    }
    return best == INF ? -1 : best;
}

