int consumable_gate_route(int nodes, std::vector<int> edges, std::vector<int> initialKeys, std::vector<int> supplies, std::vector<int> doors, int start, int goal) {
    struct Edge { int to, move, period, phase, door; };
    std::vector<std::vector<Edge>> graph(nodes);
    for (int i = 0; i + 5 < (int)edges.size(); i += 6)
        graph[edges[i]].push_back({edges[i+1], edges[i+2], edges[i+3], edges[i+4], edges[i+5]});
    int supplyCount = (int)supplies.size() / 3;
    std::vector<std::vector<int>> at(nodes);
    for (int i = 0; i < supplyCount; ++i) at[supplies[3*i]].push_back(i);
    if (start == goal) return 0;

    // State records node, remaining keys, opened doors, and collected supply records.
    using Key = std::tuple<int,int,int,int,int,int>;
    struct Item { int time; Key state; bool operator>(const Item& o) const { return time > o.time; } };
    std::priority_queue<Item, std::vector<Item>, std::greater<Item>> pq;
    std::map<Key,int> dist;
    auto acquire = [&](int node, unsigned mask, int k0, int k1) {
        for (int i : at[node]) if (!(mask & (1u << i))) {
            mask |= 1u << i;
            int kind = supplies[3*i+1], count = supplies[3*i+2];
            if (kind == 0) k0 = std::min(2, k0 + count);
            else k1 = std::min(2, k1 + count);
        }
        return std::tuple<unsigned,int,int>(mask,k0,k1);
    };
    auto [sm, sk0, sk1] = acquire(start, 0, initialKeys[0], initialKeys[1]);
    Key initial{start, sk0, sk1, 0, 0, (int)sm};
    dist[initial] = 0;
    pq.push({0, initial});
    while (!pq.empty()) {
        auto cur = pq.top(); pq.pop();
        auto it = dist.find(cur.state);
        if (it == dist.end() || it->second != cur.time) continue;
        auto [u,k0,k1,opened0,opened1,maski] = cur.state;
        if (u == goal) return cur.time;
        unsigned mask = (unsigned)maski;
        for (const auto& e : graph[u]) {
            int nk0 = k0, nk1 = k1, o0 = opened0, o1 = opened1;
            if (e.door >= 0) {
                bool opened = e.door < 32 ? (o0 & (1 << e.door)) : (o1 & (1 << (e.door-32)));
                if (!opened) {
                    int kind = doors[2*e.door], work = doors[2*e.door+1];
                    if (kind == 0) { if (nk0 == 0) continue; --nk0; }
                    else { if (nk1 == 0) continue; --nk1; }
                    if (e.door < 32) o0 |= 1 << e.door;
                    else o1 |= 1 << (e.door-32);
                    // Opening work is followed by gate timing.
                    int t = cur.time + work;
                    int wait = (e.phase - t % e.period + e.period) % e.period;
                    int arrival = t + wait + e.move;
                    auto [nm, ak0, ak1] = acquire(e.to, mask, nk0, nk1);
                    Key ns{e.to, ak0, ak1, o0, o1, (int)nm};
                    auto found = dist.find(ns);
                    if (found == dist.end() || arrival < found->second) { dist[ns] = arrival; pq.push({arrival, ns}); }
                } else {
                    int wait = (e.phase - cur.time % e.period + e.period) % e.period;
                    int arrival = cur.time + wait + e.move;
                    auto [nm, ak0, ak1] = acquire(e.to, mask, nk0, nk1);
                    Key ns{e.to, ak0, ak1, o0, o1, (int)nm};
                    auto found = dist.find(ns);
                    if (found == dist.end() || arrival < found->second) { dist[ns] = arrival; pq.push({arrival, ns}); }
                }
            } else {
                int wait = (e.phase - cur.time % e.period + e.period) % e.period;
                int arrival = cur.time + wait + e.move;
                auto [nm, ak0, ak1] = acquire(e.to, mask, nk0, nk1);
                Key ns{e.to, ak0, ak1, o0, o1, (int)nm};
                auto found = dist.find(ns);
                if (found == dist.end() || arrival < found->second) { dist[ns] = arrival; pq.push({arrival, ns}); }
            }
        }
    }
    return -1;
}

#include <vector>
#include <string>
#include <algorithm>
#include <cstdlib>
#include <limits>

int windowed_pickup_delivery(std::vector<int> weights, int capacity, std::vector<int> travel, std::vector<int> appointments) {
    const int n = static_cast<int>(weights.size());
    if (n == 0) return 0;

    const int nodes = 2 * n + 1;
    const int full = (1 << (2 * n)) - 1;
    const int INF = std::numeric_limits<int>::max() / 4;
    std::vector<int> dp((1 << (2 * n)) * nodes, INF);
    auto at = [&](int mask, int pos) -> int& {
        return dp[mask * nodes + pos];
    };

    auto finish_service = [&](int time, int node) {
        int idx = 3 * (node - 1);
        int open = appointments[idx];
        int close = appointments[idx + 1];
        int duration = appointments[idx + 2];
        int start = std::max(time, open);
        if (start > close) return INF;
        return start + duration;
    };

    at(0, 0) = 0;
    for (int mask = 0; mask <= full; ++mask) {
        for (int pos = 0; pos < nodes; ++pos) {
            int time = at(mask, pos);
            if (time == INF) continue;

            if (mask == full) {
                int ret = time + travel[pos * nodes];
                if (ret < INF) at(mask, 0) = std::min(at(mask, 0), ret);
                continue;
            }

            int load = 0;
            for (int i = 0; i < n; ++i) {
                bool picked = (mask & (1 << i)) != 0;
                bool delivered = (mask & (1 << (n + i))) != 0;
                if (picked && !delivered) load += weights[i];
            }

            for (int i = 0; i < n; ++i) {
                if (!(mask & (1 << i))) {
                    if (load + weights[i] > capacity) continue;
                    int node = i + 1;
                    int arrival = time + travel[pos * nodes + node];
                    int done = finish_service(arrival, node);
                    if (done != INF) {
                        int next = mask | (1 << i);
                        at(next, node) = std::min(at(next, node), done);
                    }
                } else if (!(mask & (1 << (n + i)))) {
                    int node = n + i + 1;
                    int arrival = time + travel[pos * nodes + node];
                    int done = finish_service(arrival, node);
                    if (done != INF) {
                        int next = mask | (1 << (n + i));
                        at(next, node) = std::min(at(next, node), done);
                    }
                }
            }
        }
    }

    int answer = INF;
    for (int pos = 1; pos < nodes; ++pos) {
        if (at(full, pos) < INF) {
            answer = std::min(answer, at(full, pos) + travel[pos * nodes]);
        }
    }
    return answer == INF ? -1 : answer;
}

#include <vector>
#include <string>
#include <algorithm>
#include <cstdlib>
#include <limits>
#include <functional>

int windowed_pickup_delivery(std::vector<int> weights, int capacity, std::vector<int> travel, std::vector<int> appointments) {
    const int n = static_cast<int>(weights.size());
    if (n == 0) return 0;
    const int m = 2 * n;
    const int INF = std::numeric_limits<int>::max() / 4;

    // A state records the completed operations and current carried load.
    // The load is determined by the visited pickup/delivery operations, but
    // keeping it explicit makes capacity checks straightforward.
    const int states = 1 << m;
    std::vector<int> dp(states * m, INF);

    auto step = [&](int prev, int next, int time) -> int {
        const int arrival = time + travel[prev * (m + 1) + next];
        const int off = 3 * (next - 1);
        const int open = appointments[off];
        const int close = appointments[off + 1];
        const int duration = appointments[off + 2];
        return std::max(arrival, open) + duration; // start must be <= close
    };

    // The final bit for each item is its delivery operation.
    for (int next = 1; next <= m; ++next) {
        if (next > n) continue; // first operation must be a pickup
        if (weights[next - 1] > capacity) continue;
        const int t = step(0, next, 0);
        if (std::max(0, appointments[3 * (next - 1)]) <= appointments[3 * (next - 1) + 1])
            dp[(1 << (next - 1)) * m + (next - 1)] = t;
    }

    for (int mask = 1; mask < states; ++mask) {
        int load = 0;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) load += weights[i];
            if (mask & (1 << (n + i))) load -= weights[i];
        }

        for (int last = 0; last < m; ++last) {
            const int time = dp[mask * m + last];
            if (time == INF) continue;

            for (int next = 0; next < m; ++next) {
                if (mask & (1 << next)) continue;
                if (next >= n) {
                    const int item = next - n;
                    if (!(mask & (1 << item))) continue; // cannot deliver before pickup
                } else {
                    if (load + weights[next] > capacity) continue;
                }

                const int start = std::max(time + travel[(last + 1) * (m + 1) + (next + 1)],
                                           appointments[3 * next]);
                if (start > appointments[3 * next + 1]) continue;
                const int finish = start + appointments[3 * next + 2];
                const int newMask = mask | (1 << next);
                int &dest = dp[newMask * m + next];
                if (finish < dest) dest = finish;
            }
        }
    }

    int answer = INF;
    const int full = states - 1;
    for (int last = 0; last < m; ++last) {
        const int time = dp[full * m + last];
        if (time == INF) continue;
        answer = std::min(answer, time + travel[(last + 1) * (m + 1)]);
    }
    return answer == INF ? -1 : answer;
}

#include <vector>
#include <string>
