int windowed_pickup_delivery(std::vector<int> weights, int capacity, std::vector<int> travel, std::vector<int> appointments) {
    const int n = static_cast<int>(weights.size());
    if (n == 0) return 0;
    const int m = 2 * n;
    const int nodes = m + 1;
    const int full = 1 << m;
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<int> load(full, 0);
    for (int mask = 1; mask < full; ++mask) {
        int bit = __builtin_ctz(static_cast<unsigned>(mask));
        load[mask] = load[mask & (mask - 1)] + ((bit < n) ? weights[bit] : 0);
    }
    std::vector<std::vector<long long>> dp(full, std::vector<long long>(nodes, INF));
    dp[0][0] = 0;
    for (int mask = 0; mask < full; ++mask) {
        for (int last = 0; last < nodes; ++last) {
            long long time = dp[mask][last];
            if (time == INF) continue;
            if (mask == full - 1) {
                long long finish = time + travel[last * nodes];
                dp[mask][0] = std::min(dp[mask][0], finish);
                continue;
            }
            for (int p = 1; p < nodes; ++p) {
                int bit = p - 1;
                int flag = 1 << bit;
                if (mask & flag) continue;
                if (bit >= n && !(mask & (1 << (bit - n)))) continue;
                int nextMask = mask | flag;
                int nextLoad = load[nextMask];
                if (nextLoad > capacity) continue;
                long long arrival = time + travel[last * nodes + p];
                int base = 3 * (p - 1);
                long long start = std::max(arrival, static_cast<long long>(appointments[base]));
                if (start > appointments[base + 1]) continue;
                long long depart = start + appointments[base + 2];
                dp[nextMask][p] = std::min(dp[nextMask][p], depart);
            }
        }
    }
    long long ans = INF;
    for (int last = 1; last < nodes; ++last)
        ans = std::min(ans, dp[full - 1][last] + travel[last * nodes]);
    return ans == INF ? -1 : static_cast<int>(ans);
}

