int consumable_gate_route(int nodes, std::vector<int> edges, std::vector<int> initialKeys, std::vector<int> supplies, std::vector<int> doors, int start, int goal) {
    if (start == goal) return 0;

    int S = static_cast<int>(supplies.size()) / 3;
    int D = static_cast<int>(doors.size()) / 2;
    int smCount = 1 << S, dmCount = 1 << D;
    std::vector<std::vector<int>> at(nodes);
    int max0 = initialKeys[0], max1 = initialKeys[1];
    for (int i = 0; i < S; ++i) {
        int v = supplies[3 * i], type = supplies[3 * i + 1], count = supplies[3 * i + 2];
        at[v].push_back(i);
        if (type == 0) max0 += count;
        else max1 += count;
    }

    auto collect = [&](int v, int &mask, int &k0, int &k1) {
        for (int i : at[v]) {
            int bit = 1 << i;
            if (!(mask & bit)) {
                mask |= bit;
                if (supplies[3 * i + 1] == 0) k0 += supplies[3 * i + 2];
                else k1 += supplies[3 * i + 2];
            }
        }
    };

    struct Edge { int to, move, period, phase, door; };
    std::vector<std::vector<Edge>> graph(nodes);
    for (int i = 0; i < static_cast<int>(edges.size()); i += 6) {
        graph[edges[i]].push_back({edges[i + 1], edges[i + 2], edges[i + 3], edges[i + 4], edges[i + 5]});
    }

    const int INF = std::numeric_limits<int>::max();
    const int k0Size = max0 + 1, k1Size = max1 + 1;
    const std::size_t total = static_cast<std::size_t>(nodes) * smCount * dmCount * k0Size * k1Size;
    std::vector<int> dist(total, INF);
    auto index = [&](int v, int sm, int dm, int k0, int k1) -> std::size_t {
        std::size_t x = v;
        x = x * smCount + sm;
        x = x * dmCount + dm;
        x = x * k0Size + k0;
        return x * k1Size + k1;
    };

    int sm = 0, k0 = initialKeys[0], k1 = initialKeys[1];
    collect(start, sm, k0, k1);
    using Item = std::tuple<int, int, int, int, int, int>;
    std::priority_queue<Item, std::vector<Item>, std::greater<Item>> pq;
    dist[index(start, sm, 0, k0, k1)] = 0;
    pq.emplace(0, start, sm, 0, k0, k1);

    while (!pq.empty()) {
        auto [time, v, usedSupplies, opened, keys0, keys1] = pq.top();
        pq.pop();
        if (dist[index(v, usedSupplies, opened, keys0, keys1)] != time) continue;
        if (v == goal) return time;

        for (const Edge &e : graph[v]) {
            int nextOpened = opened, next0 = keys0, next1 = keys1;
            int unlockTime = 0;
            if (e.door != -1 && !(opened & (1 << e.door))) {
                int type = doors[2 * e.door];
                if (type == 0) {
                    if (next0 == 0) continue;
                    --next0;
                } else {
                    if (next1 == 0) continue;
                    --next1;
                }
                nextOpened |= 1 << e.door;
                unlockTime = doors[2 * e.door + 1];
            }

            int arrival = time + unlockTime;
            int wait = (e.phase - arrival % e.period + e.period) % e.period;
            arrival += wait + e.move;

            int nextSupplies = usedSupplies;
            collect(e.to, nextSupplies, next0, next1);
            std::size_t idx = index(e.to, nextSupplies, nextOpened, next0, next1);
            if (arrival < dist[idx]) {
                dist[idx] = arrival;
                pq.emplace(arrival, e.to, nextSupplies, nextOpened, next0, next1);
            }
        }
    }
    return -1;
}

#include <vector>
#include <queue>
