int consumable_gate_route(int nodes, std::vector<int> edges, std::vector<int> initialKeys, std::vector<int> supplies, std::vector<int> doors, int start, int goal) {
    if (start == goal) return 0;

    struct Edge {
        int to, move, period, phase, door;
    };
    std::vector<std::vector<Edge>> graph(nodes);
    for (int i = 0; i < static_cast<int>(edges.size()); i += 6) {
        graph[edges[i]].push_back({edges[i + 1], edges[i + 2], edges[i + 3], edges[i + 4], edges[i + 5]});
    }

    int supplyCount = static_cast<int>(supplies.size()) / 3;
    std::vector<int> maxKeys(2, 0);
    for (int k = 0; k < 2; ++k) maxKeys[k] = initialKeys[k];
    for (int i = 0; i < static_cast<int>(supplies.size()); i += 3) {
        maxKeys[supplies[i + 1]] += supplies[i + 2];
    }

    auto encode = [](int node, int k0, int k1, int sm, int dm) -> std::uint64_t {
        std::uint64_t x = node;
        x = x * 11 + k0;
        x = x * 11 + k1;
        x = x * 16 + sm;
        x = x * 16 + dm;
        return x;
    };

    auto collect = [&](int node, int& k0, int& k1, int& sm) {
        for (int i = 0; i < supplyCount; ++i) {
            int bit = 1 << i;
            if (!(sm & bit) && supplies[3 * i] == node) {
                if (supplies[3 * i + 1] == 0) k0 += supplies[3 * i + 2];
                else k1 += supplies[3 * i + 2];
                sm |= bit;
            }
        }
    };

    int k0 = initialKeys[0], k1 = initialKeys[1], sm = 0;
    collect(start, k0, k1, sm);
    std::uint64_t initial = encode(start, k0, k1, sm, 0);

    using Item = std::pair<int, std::uint64_t>;
    std::priority_queue<Item, std::vector<Item>, std::greater<Item>> pq;
    std::unordered_map<std::uint64_t, int> dist;
    dist[initial] = 0;
    pq.push({0, initial});

    while (!pq.empty()) {
        auto [time, code] = pq.top();
        pq.pop();
        auto it = dist.find(code);
        if (it == dist.end() || it->second != time) continue;

        std::uint64_t x = code;
        int dm = static_cast<int>(x % 16); x /= 16;
        int supplyMask = static_cast<int>(x % 16); x /= 16;
        int keys1 = static_cast<int>(x % 11); x /= 11;
        int keys0 = static_cast<int>(x % 11); x /= 11;
        int node = static_cast<int>(x);

        if (node == goal) return time;

        for (const Edge& e : graph[node]) {
            int nextKeys0 = keys0, nextKeys1 = keys1, nextDm = dm;
            int ready = time;
            if (e.door >= 0 && !(dm & (1 << e.door))) {
                int required = doors[2 * e.door];
                if (required == 0) {
                    if (nextKeys0 == 0) continue;
                    --nextKeys0;
                } else {
                    if (nextKeys1 == 0) continue;
                    --nextKeys1;
                }
                ready += doors[2 * e.door + 1];
                nextDm |= 1 << e.door;
            }

            int wait = (e.phase - ready % e.period + e.period) % e.period;
            int arrival = ready + wait + e.move;

            int nextSm = supplyMask;
            collect(e.to, nextKeys0, nextKeys1, nextSm);
            std::uint64_t next = encode(e.to, nextKeys0, nextKeys1, nextSm, nextDm);
            auto jt = dist.find(next);
            if (jt == dist.end() || arrival < jt->second) {
                dist[next] = arrival;
                pq.push({arrival, next});
            }
        }
    }
    return -1;
}

