int consumable_gate_route(int nodes, std::vector<int> edges, std::vector<int> initialKeys, std::vector<int> supplies, std::vector<int> doors, int start, int goal) {
    const int keyCap = 4;
    const int supplyCount = static_cast<int>(supplies.size()) / 3;
    const int doorCount = static_cast<int>(doors.size()) / 2;
    const int supplyStates = 1 << supplyCount;
    const int doorStates = 1 << doorCount;
    const int totalStates = nodes * (keyCap + 1) * (keyCap + 1) * supplyStates * doorStates;

    auto encode = [&](int node, int k0, int k1, int sm, int dm) {
        return ((((node * (keyCap + 1) + k0) * (keyCap + 1) + k1) * supplyStates + sm) * doorStates + dm);
    };

    auto collectAt = [&](int node, int& k0, int& k1, int& sm) {
        for (int i = 0; i < supplyCount; ++i) {
            const int bit = 1 << i;
            if (!(sm & bit) && supplies[3 * i] == node) {
                sm |= bit;
                if (supplies[3 * i + 1] == 0)
                    k0 = std::min(keyCap, k0 + supplies[3 * i + 2]);
                else
                    k1 = std::min(keyCap, k1 + supplies[3 * i + 2]);
            }
        }
    };

    int startK0 = std::min(keyCap, initialKeys[0]);
    int startK1 = std::min(keyCap, initialKeys[1]);
    int startSupplyMask = 0;
    collectAt(start, startK0, startK1, startSupplyMask);
    const int source = encode(start, startK0, startK1, startSupplyMask, 0);

    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<long long> dist(totalStates, INF);
    using Item = std::pair<long long, int>;
    std::priority_queue<Item, std::vector<Item>, std::greater<Item>> pq;
    dist[source] = 0;
    pq.push({0, source});

    while (!pq.empty()) {
        auto [time, state] = pq.top();
        pq.pop();
        if (time != dist[state]) continue;

        int x = state;
        const int dm = x % doorStates;
        x /= doorStates;
        const int sm = x % supplyStates;
        x /= supplyStates;
        const int k1 = x % (keyCap + 1);
        x /= keyCap + 1;
        const int k0 = x % (keyCap + 1);
        const int node = x / (keyCap + 1);

        if (node == goal) return static_cast<int>(time);

        for (int e = 0; e < static_cast<int>(edges.size()); e += 6) {
            if (edges[e] != node) continue;
            const int to = edges[e + 1];
            const int travel = edges[e + 2];
            const int period = edges[e + 3];
            const int phase = edges[e + 4];
            const int doorId = edges[e + 5];

            int nextK0 = k0, nextK1 = k1;
            int nextDm = dm;
            long long departReady = time;
            if (doorId >= 0 && !(dm & (1 << doorId))) {
                const int requiredKey = doors[2 * doorId];
                if (requiredKey == 0) {
                    if (nextK0 == 0) continue;
                    --nextK0;
                } else {
                    if (nextK1 == 0) continue;
                    --nextK1;
                }
                departReady += doors[2 * doorId + 1];
                nextDm |= 1 << doorId;
            }

            const int remainder = static_cast<int>(departReady % period);
            if (remainder != phase)
                departReady += (phase - remainder + period) % period;
            const long long arrival = departReady + travel;

            int nextSm = sm;
            collectAt(to, nextK0, nextK1, nextSm);
            const int nextState = encode(to, nextK0, nextK1, nextSm, nextDm);
            if (arrival < dist[nextState]) {
                dist[nextState] = arrival;
                pq.push({arrival, nextState});
            }
        }
    }
    return -1;
}
